INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT135-S1-Q3$batch13$, 135, 1, 3, $batch13$Evaluate$batch13$, $batch13$Millions of homes are now using low-energy lighting, but millions more have still to make the switch, a fact that the government and the home lighting industry are eager to change. Although low-wattage bulbs cost more per bulb than normal bulbs, their advantages to the homeowner are enormous, and therefore everyone should use low-wattage bulbs.$batch13$, $batch13$Information about which one of the following would be least useful in evaluating the argument?$batch13$, $batch13$B$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=135 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT135-S1-Q3$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$the actual cost of burning low-wattage bulbs compared to that of burning normal bulbs$batch13$, $batch13$Useful$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$the profits the home lighting industry expects to make from sales of low-wattage bulbs$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$the specific cost of a low-wattage bulb compared with that of a normal bulb$batch13$, $batch13$Useful$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$the opinion of current users of low-wattage bulbs as to their effectiveness$batch13$, $batch13$Useful$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$the average life of a low-wattage bulb compared with that of a normal bulb$batch13$, $batch13$Useful$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Everyone should use low-wattage bulbs.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Low-wattage bulbs cost more per bulb, but their advantages to homeowners are enormous.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The argument weighs costs against benefits to homeowners. Four choices give facts that would test that balance: running cost, bulb price, lifespan, and how well the bulbs work. The answer is the one that doesn't touch the homeowner's costs or benefits.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find the least useful information: something outside the homeowner's costs and benefits.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Running cost is a key part of the homeowner's advantage.$batch13$), ($batch13$B$batch13$, $batch13$The industry's expected profits don't change the costs or benefits to homeowners.$batch13$), ($batch13$C$batch13$, $batch13$The price gap is the cost side of the argument.$batch13$), ($batch13$D$batch13$, $batch13$Users' views on effectiveness bear on the claimed advantages.$batch13$), ($batch13$E$batch13$, $batch13$A longer life would offset the higher price.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT135-S1-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
